command:
// Lantern Night in Hallowby: a new raid on Easy, with Hallowby's shopping list on the Raid HUD.
// Run it as the Storyteller once each player owns their Entity: the raid takes every Entity with a player owner.
const run = game.dontGetForked.runOp;
const raid = await run("raid.reset", { difficulty: "easy" });
if (!raid?.ok) return ui.notifications.warn(`New raid refused: ${raid?.reason ?? "no reply"}`);
await run("raid.list", { action: "set", list: [
  { name: "a cask of red wine (“for the guests”)", duty: "cook", essential: true },
  { name: "a pot of nightshade (purely ornamental)", duty: "gardener", essential: false },
  { name: "hinges that creak properly", duty: "handyman", essential: false },
  { name: "a new cape", duty: "tailor", essential: false }
] });
ui.notifications.info("Hallowby: a new Easy raid, with its shopping list.");
